package com.bananalab.lite;
import java.util.*;
public final class Stage50SpecialistCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[] args)throws Exception{JavaEditModel m=new JavaEditModel();String initial=m.json().toString();m.train();check(!initial.equals(m.json().toString()),"model weights actually trained from random initialization");check(m.trainCorrect>=34&&m.testCorrect>=8,"training and separate phrase evaluation: "+m.trainCorrect+"/36 "+m.testCorrect+"/12");System.out.println("METRICS base="+m.trainCorrect+"/36 validation="+m.testCorrect+"/12 final="+m.finalCorrect+"/12");for(int i=0;i<6;i++)System.out.println(JavaEditModel.OPS[i]+" prediction="+JavaEditModel.OPS[m.predict(JavaEditModel.HELDOUT[i][0])]);JavaEditModel copy=JavaEditModel.read(m.json().toString());check(copy.predict("dividir los valores")==3,"trained parameters reload");String source="package com.bananalab.lite; final class Cuenta{ static float valor(float a,float b){ return a-b; } static String otro(){ return \"llave }\"; } }";String changed=JavaSourceEdit.arithmetic(source,"valor","+");check(changed.contains("return (a) + (b);")&&changed.contains("return \"llave }\";"),"generated operator edit preserves other method and string brace");String nested="class Uno { static int valor(int a){ /* } */ return a; } }";check(JavaSourceEdit.replace(nested,"valor","return a+1;").contains("return a+1;"),"method scanner respects comments");try{JavaSourceEdit.filename("../Otro.java");throw new AssertionError("path traversal");}catch(IllegalArgumentException expected){}try{JavaSourceEdit.method("class A{int x(){return 1;} int x(int y){return y;}}","x");throw new AssertionError("ambiguous method");}catch(IllegalArgumentException expected){}try{JavaSourceEdit.arithmetic(source.replace("a-b","a-b+1"),"valor","+");throw new AssertionError("ambiguous arithmetic");}catch(IllegalArgumentException expected){}System.out.println("PASS Stage50 own MLP training, phrase holdout, saved weights and actual source operator generation beyond chat method");}
}
